Step.SQLStatement:
DELETE FROM AD_FieldCustom_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_Field f ON(f.AD_Column_ID = c.AD_Column_ID) INNER JOIN AD_FieldCustom fc ON(fc.AD_Field_ID = f.AD_Field_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Commission') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID') AND fc.AD_FieldCustom_ID = AD_FieldCustom_Trl.AD_FieldCustom_ID);
DELETE FROM AD_FieldCustom WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_Field f ON(f.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Commission') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID') AND f.AD_Field_ID = AD_FieldCustom.AD_Field_ID);
DELETE FROM AD_Field WHERE EXISTS(SELECT 1 FROM AD_Column c WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Commission') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID') AND c.AD_Column_ID = AD_Field.AD_Column_ID);
DELETE FROM AD_Browse_Field_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) INNER JOIN AD_Browse_Field bf ON(bf.AD_View_Column_ID = vc.AD_View_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Commission') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID') AND bf.AD_Browse_Field_ID = AD_Browse_Field_Trl.AD_Browse_Field_ID);
DELETE FROM AD_Browse_Field WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Commission') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID') AND vc.AD_View_Column_ID = AD_Browse_Field.AD_View_Column_ID);
DELETE FROM AD_View_Column_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Commission') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID') AND vc.AD_View_Column_ID = AD_View_Column_Trl.AD_View_Column_ID);
DELETE FROM AD_View_Column WHERE EXISTS(SELECT 1 FROM AD_Column c WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Commission') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID') AND c.AD_Column_ID = AD_View_Column.AD_Column_ID);
DELETE FROM AD_Column WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = AD_Column.AD_Table_ID AND t.TableName = 'C_Commission') AND AD_Column_ID >= 1000000 AND ColumnName IN('C_DocTypeOrder_ID', 'M_Product_ID');
DELETE FROM AD_Element WHERE ColumnName = 'C_DocTypeOrder_ID' AND AD_Element_ID > 1000000;
